/// Functions unsupported in code generation.
const UNSUPPORTED_FUNCTIONS: &[&str] = &[
    "eval",
    "evalc",
    "evalin",
    "feval",
    "assignin",
    "input",
    "keyboard",
    "dbstop",
    "dbclear",
    "dbcont",
