    }

    // -- PUSE: persistent declared but not used ------------------------------

    #[test]
    fn puse_fires_on_unused_persistent() {
        let diags = lint_file(&*engine(), "function foo()\n    persistent p;\nend\n");
        assert!(has_id(&diags, "PUSE"), "got: {diags:?}");
