//! NCOMMA check: output variables not separated by commas.

use super::*;

impl FormattingEngine {
    /// For `multioutput_variable` nodes (assignment LHS or function output
    /// declaration), flag elements separated by whitespace instead of commas
    /// (e.g., `[a b] = f()` should be `[a, b]`).
    pub(crate) fn check_ncomma(&self, node: Node, source: &str, diagnostics: &mut Vec<Diagnostic>) {
        let mut elements: Vec<Node> = Vec::new();
        let child_count = node.child_count();
        for i in 0..child_count {
            let Some(child) = node.child(i) else {
                continue;
            };
            if matches!(
                child.kind(),
                "identifier" | "field_expression" | "ignored_argument" | "function_call"
            ) {
                elements.push(child);
            }
        }

        for pair in elements.windows(2) {
            let gap = &source[pair[0].end_byte()..pair[1].start_byte()];
            if gap.contains(',') {
                continue;
            }
            let pos = pair[1].start_position();
            let insert_pos = pair[1].start_byte();
            diagnostics.push(Diagnostic {
                rule_id: "NCOMMA",
                message: "Best practice is to separate output variables with commas."
                    .to_string(),
                severity: Severity::Info,
                byte_range: pair[0].end_byte()..pair[1].start_byte(),
                line: pos.row + 1,
                column: pos.column + 1,
                fix: Some(Fix::insert(insert_pos, ", ")),
            });
        }
    }
}

#[cfg(test)]
mod tests {

    use crate::formatting::tests::{has_id, lint};

    // -- NCOMMA --------------------------------------------------------------

    #[test]
    fn ncomma_space_separated_output() {
        let source = "[a b] = f();\n";
        let diags = lint(source);
        assert!(has_id(&diags, "NCOMMA"), "got: {diags:?}");
    }

    #[test]
    fn ncomma_comma_separated_output_ok() {
        let source = "[a, b] = f();\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "NCOMMA"), "got: {diags:?}");
    }

    #[test]
    fn ncomma_space_separated_function_output() {
        let source = "function [a b] = f()\n    a = 1;\n    b = 2;\nend\n";
        let diags = lint(source);
        assert!(has_id(&diags, "NCOMMA"), "got: {diags:?}");
    }
}

//! NOPTS check: statement in a script that produces output without a semicolon.

use super::*;

impl FormattingEngine {
    /// Flag an `assignment` statement at script level that is not terminated by
    /// a semicolon, so it echoes its result to the console.
    pub(crate) fn check_nopts(&self, node: Node, source: &str, diagnostics: &mut Vec<Diagnostic>) {
        let is_statement_level = node
            .parent()
            .map(|p| STATEMENT_PARENTS.contains(&p.kind()))
            .unwrap_or(false);
        if !is_statement_level {
            return;
        }
        // Only scripts (not function bodies).
        if is_in_function(node) {
            return;
        }
        if has_trailing_semicolon(node, source) {
            return;
        }

        let start = node.start_position();
        let end_byte = node.end_byte();
        diagnostics.push(Diagnostic {
            rule_id: "NOPTS",
            message: "Add a semicolon after the statement to hide the output (in a script)."
                .to_string(),
            severity: Severity::Info,
            byte_range: node.start_byte()..node.end_byte(),
            line: start.row + 1,
            column: start.column + 1,
            fix: Some(Fix::insert(end_byte, ";")),
        });
    }
}

#[cfg(test)]
mod tests {

    use crate::formatting::tests::{has_id, lint};

    // -- NOPTS ---------------------------------------------------------------

    #[test]
    fn nopts_assignment_in_script_without_semicolon() {
        let source = "x = 5\n";
        let diags = lint(source);
        assert!(has_id(&diags, "NOPTS"), "got: {diags:?}");
    }

    #[test]
    fn nopts_ok_with_semicolon() {
        let source = "x = 5;\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "NOPTS"), "got: {diags:?}");
    }

    #[test]
    fn nopts_not_fire_in_function() {
        let source = "function f()\n    x = 5\nend\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "NOPTS"), "got: {diags:?}");
    }
}

//! NOPRT check: statement in a function that produces output without a semicolon.

use super::*;

impl FormattingEngine {
    /// Flag an `assignment` statement inside a function that is not terminated
    /// by a semicolon, so it echoes its result to the console.
    pub(crate) fn check_noprt(&self, node: Node, source: &str, diagnostics: &mut Vec<Diagnostic>) {
        let is_statement_level = node
            .parent()
            .map(|p| STATEMENT_PARENTS.contains(&p.kind()))
            .unwrap_or(false);
        if !is_statement_level {
            return;
        }
        // Only function bodies (not scripts).
        if !is_in_function(node) {
            return;
        }
        if has_trailing_semicolon(node, source) {
            return;
        }

        let start = node.start_position();
        let end_byte = node.end_byte();
        diagnostics.push(Diagnostic {
            rule_id: "NOPRT",
            message: "Add a semicolon after the statement to hide the output (in a function)."
                .to_string(),
            severity: Severity::Info,
            byte_range: node.start_byte()..node.end_byte(),
            line: start.row + 1,
            column: start.column + 1,
            fix: Some(Fix::insert(end_byte, ";")),
        });
    }
}

#[cfg(test)]
mod tests {

    use crate::formatting::tests::{has_id, lint};

    // -- NOPRT ---------------------------------------------------------------

    #[test]
    fn noprt_assignment_in_function_without_semicolon() {
        let source = "function f()\n    x = 5\nend\n";
        let diags = lint(source);
        assert!(has_id(&diags, "NOPRT"), "got: {diags:?}");
    }

    #[test]
    fn noprt_ok_with_semicolon() {
        let source = "function f()\n    x = 5;\nend\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "NOPRT"), "got: {diags:?}");
    }

    #[test]
    fn noprt_not_fire_in_script() {
        let source = "x = 5\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "NOPRT"), "got: {diags:?}");
    }
}

//! PRTCAL check: bare function call statement without a trailing semicolon.

use super::*;

impl FormattingEngine {
    /// Flag a `function_call` used as a bare statement (producing output) that
    /// is not terminated by a semicolon.
    pub(crate) fn check_prtcal(&self, node: Node, source: &str, diagnostics: &mut Vec<Diagnostic>) {
        let is_statement_level = node
            .parent()
            .map(|p| STATEMENT_PARENTS.contains(&p.kind()))
            .unwrap_or(false);
        if !is_statement_level {
            return;
        }
        if has_trailing_semicolon(node, source) {
            return;
        }

        let start = node.start_position();
        let end_byte = node.end_byte();
        diagnostics.push(Diagnostic {
            rule_id: "PRTCAL",
            message: "Add a semicolon after the function call to hide the output.".to_string(),
            severity: Severity::Info,
            byte_range: node.start_byte()..node.end_byte(),
            line: start.row + 1,
            column: start.column + 1,
            fix: Some(Fix::insert(end_byte, ";")),
        });
    }
}

#[cfg(test)]
mod tests {

    use crate::formatting::tests::{has_id, lint};

    // -- PRTCAL --------------------------------------------------------------

    #[test]
    fn prtcal_function_call_without_semicolon() {
        let source = "disp('hello')\n";
        let diags = lint(source);
        assert!(has_id(&diags, "PRTCAL"), "got: {diags:?}");
    }

    #[test]
    fn prtcal_ok_with_semicolon() {
        let source = "disp('hello');\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "PRTCAL"), "got: {diags:?}");
    }

    #[test]
    fn prtcal_ok_when_not_statement_level() {
        let source = "x = compute(1);\n";
        let diags = lint(source);
        assert!(!has_id(&diags, "PRTCAL"), "got: {diags:?}");
    }
}

